import re

def word_count(s: str) -> dict[str, int]:
    words = re.findall(r'[A-Za-z]+', s)
    counts: dict[str, int] = {}
    for w in words:
        lw = w.lower()
        counts[lw] = counts.get(lw, 0) + 1
    return counts
